569	type ProcedurePath = {
570	  [Router in keyof RouterInputs & string]: `${Router}.${keyof RouterInputs[Router] & string}`;
571	}[keyof RouterInputs & string];
572	
573	type Lookup<Tree, Path> = Path extends `${infer Router}.${infer Procedure}`
574	  ? Router extends keyof Tree
575	    ? Procedure extends keyof Tree[Router]
576	      ? Tree[Router][Procedure]
577	      : never
578	    : never
579	  : never;
