581	/** A fake answer per procedure path, such as `'greeting.greet'`, typed by the router. */
582	export type TestApiHandlers = {
583	  readonly [Path in ProcedurePath]?: (
584	    input: Lookup<RouterInputs, Path>,
585	  ) => Lookup<RouterOutputs, Path> | Promise<Lookup<RouterOutputs, Path>>;
586	};
587	
588	/** A tRPC link that answers each call from `handlers` instead of the network. */
589	export function handlerLink(handlers: TestApiHandlers): TRPCLink<AppRouter> {
590	  return () =>
591	    ({ op }) =>
592	      observable((observer) => {
593	        const handler = handlers[op.path as ProcedurePath] as
594	          | ((input: unknown) => unknown)
595	          | undefined;
596	        Promise.resolve(op.input)
597	          .then((input) => {
598	            if (!handler) {
599	              throw new Error(`TestApiProvider has no handler for ${op.path}`);
600	            }
601	            return handler(input);
602	          })
603	          .then(
604	            (data) => {
605	              observer.next({ result: { type: 'data', data } });
606	              observer.complete();
607	            },
608	            (cause: Error) => observer.error(TRPCClientError.from(cause)),
609	          );
610	      });
