export { TextField, type TextFieldProps } from './TextField';
import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { axe } from 'jest-axe';
import { Button } from './Button';

it('renders a button that does not submit a form unless asked to', async () => {
  const handleSubmit = jest.fn((event: SubmitEvent) => event.preventDefault());
  render(
    <form onSubmit={(event) => handleSubmit(event.nativeEvent as SubmitEvent)}>
      <Button>Plain</Button>
      <Button type="submit">Send</Button>
    </form>,
  );

  await userEvent.click(screen.getByRole('button', { name: 'Plain' }));
  expect(handleSubmit).not.toHaveBeenCalled();

  await userEvent.click(screen.getByRole('button', { name: 'Send' }));
  expect(handleSubmit).toHaveBeenCalledTimes(1);
});

it('calls its click handler and has no axe-detectable violations', async () => {
  const handleClick = jest.fn();
  const { container } = render(<Button onClick={handleClick}>Press</Button>);

  await userEvent.click(screen.getByRole('button', { name: 'Press' }));

  expect(handleClick).toHaveBeenCalledTimes(1);
  expect(await axe(container)).toHaveNoViolations();
});
import type { ComponentProps } from 'react';

export type ButtonProps = ComponentProps<'button'>;

export function Button({ type = 'button', className, ...props }: ButtonProps) {
  return (
    <button type={type} className={['ui-button', className].filter(Boolean).join(' ')} {...props} />
  );
}
import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { axe } from 'jest-axe';
import { TextField } from './TextField';

it('labels its input and passes typed text through', async () => {
  const handleChange = jest.fn();
  render(<TextField label="Name" onChange={handleChange} />);

  const field = screen.getByRole('textbox', { name: 'Name' });
  await userEvent.type(field, 'Ada');

  expect(field).toHaveValue('Ada');
  expect(field).toBeValid();
  expect(screen.queryByRole('alert')).not.toBeInTheDocument();
});

it('announces an error and ties it to the input', async () => {
  const { container } = render(<TextField label="Name" error="Enter a name" />);

  const field = screen.getByRole('textbox', { name: 'Name' });
  expect(screen.getByRole('alert')).toHaveTextContent('Enter a name');
  expect(field).toBeInvalid();
  expect(field).toHaveAccessibleDescription('Enter a name');
  expect(await axe(container)).toHaveNoViolations();
});

it('forwards a ref to the input', () => {
  const ref = { current: null as HTMLInputElement | null };
  render(<TextField label="Name" ref={ref} />);

  expect(ref.current).toBe(screen.getByRole('textbox', { name: 'Name' }));
});

it('keeps the error tied to the input when the caller passes its own description', () => {
  render(<TextField label="Name" error="Enter a name" aria-describedby="elsewhere" />);

  expect(screen.getByRole('textbox', { name: 'Name' })).toHaveAccessibleDescription('Enter a name');
});

it('adds a caller class name to its own', () => {
  render(<TextField label="Name" className="wide" />);

  expect(screen.getByRole('textbox', { name: 'Name' })).toHaveClass('ui-text-field__input', 'wide');
});
import { type ComponentProps, useId } from 'react';

export interface TextFieldProps extends Omit<ComponentProps<'input'>, 'id'> {
  readonly label: string;
  readonly error?: string | undefined;
}

export function TextField({ label, error, className, ...inputProps }: TextFieldProps) {
  const inputId = useId();
  const errorId = `${inputId}-error`;
  return (
    <div className="ui-text-field">
      <label className="ui-text-field__label" htmlFor={inputId}>
        {label}
      </label>
      <input
        {...inputProps}
        id={inputId}
        className={['ui-text-field__input', className].filter(Boolean).join(' ')}
        aria-invalid={error ? true : undefined}
        aria-describedby={error ? errorId : undefined}
      />
      {error ? (
        <p id={errorId} role="alert" className="ui-text-field__error">
          {error}
        </p>
      ) : null}
    </div>
  );
}
