// TEMPLATE — copy next to the component as __Name__.test.tsx, for example
// <result>/web/src/routes/<route-name>/__Name__Page.test.tsx.
// Model: apps/web/src/routes/greeting/GreetingPage.test.tsx.
//
// Render through TestApiProvider from the api client whenever the component
// (or a hook it calls) reaches the api. Give one typed handler per procedure
// path the test needs; a missing handler fails the call with its path. Drop
// the provider for a component that never calls the api.
// Assert on observable behaviour through the accessibility tree (roles, names,
// live regions), one `it` per behaviour. See .claude/skills/write-unit-tests/SKILL.md.

import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { axe } from 'jest-axe';
import { type TestApiHandlers, TestApiProvider } from '../../api-client';
import { __Name__Page } from './__Name__Page';

function renderPage(__procedure__: NonNullable<TestApiHandlers['__router__.__procedure__']>) {
  const view = render(
    <TestApiProvider handlers={{ '__router__.__procedure__': __procedure__ }}>
      <__Name__Page />
    </TestApiProvider>,
  );
  return { ...view, user: userEvent.setup() };
}

it('__describes what the user sees after an action that reaches the api__', async () => {
  const __procedure__ = jest.fn((input: __Input__) => (__output__));
  const { user } = renderPage(__procedure__);

  await user.click(screen.getByRole('button', { name: '__Action__' }));

  expect(await screen.findByRole('status')).toHaveTextContent('__expected outcome__');
  expect(__procedure__).toHaveBeenCalledWith(__expected input__);
});

it('says so when the api fails', async () => {
  const { user } = renderPage(() => Promise.reject(new Error('api down')));

  await user.click(screen.getByRole('button', { name: '__Action__' }));

  expect(await screen.findByRole('alert')).toHaveTextContent('__error message__');
});

it('has no axe-detectable violations', async () => {
  const { container } = renderPage(() => (__output__));

  expect(await axe(container)).toHaveNoViolations();
});
// TEMPLATE — copy to <result>/web/src/routes/<route-name>/__Name__.tsx (for example
// apps/web/src/routes/<route-name>/) and replace the __PLACEHOLDERS__.
// Model: apps/web/src/routes/greeting/GreetingForm.tsx and GreetingPage.tsx.
//
// One component per file, named like the file. A component only renders: it
// takes state from its use* hook (server state through useTrpc(), form state
// through use__Name__Form) and builds controls from @repo/ui. Functions it
// defines start with `handle`; callback props start with `on`.
// See .agents/project/ARCHITECTURE.md.

import { Button } from '@repo/ui';
import { use__Name__ } from './use__Name__';

export interface __Name__Props {
  readonly on__Event__: (value: string) => void;
}

export function __Name__({ on__Event__ }: __Name__Props) {
  const { /* values from the hook */ } = use__Name__();

  function handle__Action__() {
    on__Event__('__value__');
  }

  return (
    <section className="__route-name__" aria-label="__Accessible name__">
      {/* Render observable state. Keep every interactive element a real,
          labelled control so the behaviour map and a11y tooling can reach it. */}
      <Button onClick={handle__Action__}>__Action__</Button>
    </section>
  );
}
// TEMPLATE — copy to <result>/web/e2e/<route-name>.spec.ts, for example
// apps/web/e2e/<route-name>.spec.ts. Playwright (`pnpm e2e`) runs every spec in
// each result's web/e2e/ against that result's real api and Vite servers.
// Model: apps/web/e2e/greeting.spec.ts.
//
// This is the BEHAVIOUR MAP: the product's contract from the user's point of
// view. Drive the real UI; assert via the accessibility tree. Keep it about
// WHAT the product does, not HOW it is built.
// See .claude/skills/run-e2e-tests/SKILL.md.

import { expect, type Page, test } from '@playwright/test';

async function submit__Value__(page: Page, value: string) {
  await page.goto('/');
  await page.getByRole('textbox', { name: '__Field label__' }).fill(value);
  await page.getByRole('button', { name: '__Action__' }).click();
}

test.describe('__Route__', () => {
  test('__describes the user-visible journey through the api__', async ({ page }) => {
    const answered = page.waitForResponse((response) =>
      response.url().includes('/trpc/__router__.__procedure__'),
    );

    await submit__Value__(page, '__value__');

    expect((await answered).status()).toBe(200);
    await expect(page.getByRole('status')).toHaveText('__expected outcome__');
  });

  test('__describes the validation message for bad input__', async ({ page }) => {
    await submit__Value__(page, '__invalid value__');

    await expect(page.getByRole('alert')).toHaveText('__validation message__');
  });

  test('says so when the api fails', async ({ page }) => {
    await page.route('**/trpc/**', (route) =>
      route.fulfill({ status: 500, contentType: 'application/json', body: '{}' }),
    );

    await submit__Value__(page, '__value__');

    await expect(page.getByRole('alert')).toHaveText('__error message__');
  });
});
