          className="todo-item__checkbox"
          checked={todo.completed}
          onChange={handleToggle}
        />
        <span className={todo.completed ? 'todo-item__title--completed' : undefined}>
          {todo.title}
        </span>
      </label>
      <Button aria-label={`Delete ${todo.title}`} onClick={handleDelete}>
        Delete
      </Button>
    </li>
  );
}
